<script setup>
import {routePath,sitePath} from '../paths.js';

import {ref,computed,onBeforeUnmount} from 'vue';import {ArrowUpRight,ArrowLeft,Pause,Play,Maximize2} from 'lucide-vue-next';import {makeProject,templates} from './templates.js';import {presets} from '../studio/presets.js';import ScreenPlayer from './components/ScreenPlayer.vue';import './runtime/screen.css';
const choices=['city','agriculture','industry','campus'].map(id=>templates.find(t=>t.id===id)),initial=routePath().split('/')[2],selected=ref(choices.some(t=>t.id===initial)?initial:'city'),quality=ref('balanced'),project=ref(makeProject(selected.value)),playing=ref(true),loadingId=ref(''),current=computed(()=>choices.find(t=>t.id===selected.value));
const imageCache=new Map();let choice=0;
function warm(id){const t=templates.find(t=>t.id===id),url=presets.find(p=>p.id===t?.header)?.background.url;if(!url)return Promise.resolve();if(!imageCache.has(url))imageCache.set(url,new Promise(resolve=>{const image=new Image();let settled=false;const finish=()=>{if(settled)return;settled=true;clearTimeout(timeout);resolve();};const timeout=setTimeout(()=>{imageCache.delete(url);finish();},8000);image.onload=()=>{image.decode().catch(()=>{}).finally(finish);};image.onerror=()=>{imageCache.delete(url);finish();};image.src=sitePath(url);}));return imageCache.get(url);}
async function choose(id){if(id===selected.value&&!loadingId.value)return;const request=++choice;loadingId.value=id;await warm(id);if(request!==choice)return;selected.value=id;project.value=makeProject(id);applyQuality();history.replaceState({},'',sitePath(`/templates/${id}/`));document.title=project.value.name+' · Astra Gallery';loadingId.value='';}
function applyQuality(){for(const n of project.value.nodes)if(['scene','model','globe','map'].includes(n.type))n.props.quality=quality.value;}
document.title=project.value.name+' · Astra Gallery';warm(selected.value);function fullscreen(){document.documentElement.requestFullscreen?.();}
function key(e){if(e.altKey||e.metaKey||e.ctrlKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;const i=choices.findIndex(t=>t.id===selected.value);if(e.key==='ArrowRight')choose(choices[(i+1)%choices.length].id);if(e.key==='ArrowLeft')choose(choices[(i+choices.length-1)%choices.length].id);}
document.addEventListener('keydown',key);onBeforeUnmount(()=>document.removeEventListener('keydown',key));
</script>
<template><main class="aw-showcase" :style="{'--gallery-accent':current.color}"><ScreenPlayer :key="project.id" :project="project" :assets="{}" :playing="playing"/><nav class="aw-showcase-nav" aria-label="行业模板预览"><a :href="sitePath('/?panel=templates')" aria-label="返回模板库"><ArrowLeft :size="14"/></a><i></i><button v-for="t in choices" :key="t.id" :aria-pressed="selected===t.id" :class="{active:selected===t.id,waiting:loadingId===t.id}" :aria-busy="loadingId===t.id" @pointerenter="warm(t.id)" @focus="warm(t.id)" @click="choose(t.id)"><span :style="{background:t.color}"></span>{{{city:'城市',agriculture:'农业',industry:'工业',campus:'园区'}[t.id]}}</button><i></i><select v-model="quality" aria-label="画面品质" title="画面品质" @change="applyQuality"><option value="performance">流畅</option><option value="balanced">均衡</option><option value="high">细腻</option></select><button :aria-label="playing?'暂停动效':'播放动效'" @click="playing=!playing"><component :is="playing?Pause:Play" :size="13"/></button><button aria-label="全屏查看" @click="fullscreen"><Maximize2 :size="13"/></button><a class="aw-showcase-use" :href="sitePath('/?template='+selected)">使用此模板<ArrowUpRight :size="12"/></a></nav></main></template>
<style>.aw-showcase{position:fixed;inset:0;background:#050c12;font-family:Inter,'PingFang SC',sans-serif}.aw-showcase-nav{position:fixed;z-index:500;left:50%;bottom:12px;transform:translateX(-50%);display:flex;align-items:center;gap:3px;background:#0a121bea;backdrop-filter:blur(12px);border:1px solid #cad7e322;box-shadow:0 7px 30px #0004;border-radius:10px;padding:5px;white-space:nowrap;opacity:.42;transition:opacity .2s}.aw-showcase-nav:hover,.aw-showcase-nav:focus-within{opacity:1}.aw-showcase-nav>button,.aw-showcase-nav>a{border:0;background:none;color:#899aa9;font:11px Inter,'PingFang SC',sans-serif;display:flex;align-items:center;gap:6px;border-radius:5px;padding:8px 10px;cursor:pointer;text-decoration:none}.aw-showcase-nav>button:hover,.aw-showcase-nav>a:hover{background:#ffffff08;color:#e1e9ef}.aw-showcase-nav>button.waiting>span{animation:aw-gallery-load .7s ease-in-out infinite alternate}@keyframes aw-gallery-load{to{opacity:.2;box-shadow:0 0 0 3px #ffffff18}}.aw-showcase-nav>button.active{background:color-mix(in srgb,var(--gallery-accent) 13%,transparent);color:var(--gallery-accent)}.aw-showcase-nav>button>span{width:4px;height:4px;border-radius:50%;opacity:.7}.aw-showcase-nav>select{border:0;border-radius:4px;padding:6px 4px;color:#a4b4c2;background:#192330;font:10px Inter,'PingFang SC',sans-serif;outline:none;cursor:pointer;margin:0 3px}.aw-showcase-nav>select:focus-visible{outline:1px solid var(--gallery-accent)}.aw-showcase-nav>i{height:14px;width:1px;background:#ccddeb14;margin:0 3px}.aw-showcase-nav>.aw-showcase-use{margin-left:3px;background:#e8f1f20e;color:#c6d8dc}@media(max-width:600px){.aw-showcase-nav{gap:0;bottom:8px}.aw-showcase-nav>button,.aw-showcase-nav>a{font-size:9px;padding:7px}.aw-showcase-nav>select{border:0;border-radius:4px;padding:6px 4px;color:#a4b4c2;background:#192330;font:10px Inter,'PingFang SC',sans-serif;outline:none;cursor:pointer;margin:0 3px}.aw-showcase-nav>select:focus-visible{outline:1px solid var(--gallery-accent)}.aw-showcase-nav>i{margin:0 1px}}@media(max-width:520px){.aw-showcase-nav{max-width:calc(100vw - 16px);overflow-x:auto;scrollbar-width:none}.aw-showcase-nav>button,.aw-showcase-nav>a,.aw-showcase-nav>select{flex-shrink:0}}@media(prefers-reduced-motion:reduce){.aw-showcase-nav{transition:none}.aw-showcase-nav>button.waiting>span{animation:none}}</style>
